parameters.jsCode:
const results = [];

for (const item of items) {
  const el = item.json;

  // Get coordinates
  let lat = el.lat || (el.center ? el.center.lat : null);
  let lon = el.lon || (el.center ? el.center.lon : null);

  if (!lat || !lon) continue;

  const tags = el.tags || {};
  const name = tags.name || tags['addr:street'] || 'Unnamed';

  // Classify site type
  let site_type = 'industrial';
  let landuse = tags.landuse || '';
  let building = tags.building || '';
  let manMade = tags.man_made || '';
  let amenity = tags.amenity || '';

  if (landuse === 'brownfield') site_type = 'brownfield';
  else if (landuse === 'landfill') site_type = 'landfill';
  else if (landuse === 'construction') site_type = 'construction';
  else if (manMade === 'wastewater_plant') site_type = 'sewage';
  else if (manMade === 'chimney') site_type = 'chimney_stack';
  else if (amenity === 'waste_disposal' || amenity === 'recycling') site_type = 'waste_facility';
  else if (building === 'warehouse') site_type = 'warehouse';
  else if (building === 'industrial') site_type = 'industrial_building';
  else if (tags.abandoned || tags.disused === 'yes') site_type = 'abandoned';
  else if (tags.ruins === 'yes') site_type = 'ruins';
  else if (tags.industrial) site_type = 'industrial_' + tags.industrial;

  // Determine decay relevance
  let category = 'infrastructure';
  if (['brownfield','landfill','sewage','abandoned','ruins'].includes(site_type)) {
    category = 'decay';
  } else if (['waste_facility'].includes(site_type)) {
    category = 'decay';
  } else if (site_type === 'construction') {
    category = 'infrastructure';
  }

  results.push({
    json: {
      latitude: Math.round(lat * 100000) / 100000,
      longitude: Math.round(lon * 100000) / 100000,
      name: name,
      site_type: site_type,
      category: category,
      osm_id: el.id,
      osm_type: el.type,
      landuse: landuse,
      building: building,
      source: 'OpenStreetMap Overpass'
    }
  });
}

return results;
